// Starter pack — GLBs that ship in-repo so a fresh OpenLen deploy has models
// to show in the 3D panel immediately.
//
// To seed an instance: `npm run models:seed`. That uploads each GLB to
// object storage and inserts a row in `models`. After seed, add more via
// `npm run models:add`.
//
// Contents:
//   - 2 objects from the Khronos glTF Sample Assets repository
//     (https://github.com/KhronosGroup/glTF-Sample-Assets), CC-BY 4.0.
//   - 8 procedural DECORATIVE sculptures generated by OpenLen (scratch/
//     procgen-scene.js → GLTFExporter), CC0.

import type { ModelFamily } from "@/lib/models/families";

export interface StarterModelEntry {
  id: string;
  name: string;
  family: ModelFamily;
  author: string;
  pitch: string;
  description: string;
  fileName: string;
  license: string;
  sceneSpec?: Record<string, unknown>;
}

